let drawerDraft=null,drawerDirty=false,returnFocus=null,searchTimer;
const localDate=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Windhoek',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return p.year+'-'+p.month+'-'+p.day};
function sizesFor(pid){const p=data.products.find(p=>num(p.id)===num(pid));if(!p)return data.sizes;const sizes=data.sizes.filter(s=>s.measurement_type===p.costing_basis||(p.costing_basis==='ready_made'&&s.measurement_type==='count'));if(['count','ready_made'].includes(p.costing_basis)&&!sizes.some(s=>num(s.id)===0))sizes.unshift({id:0,label:'1 unit'});return sizes}
const options=(rows,value,label)=>rows.map(r=>'<option value="'+esc(value(r))+'">'+esc(label(r))+'</option>').join('');
const attributeLabel=value=>{try{const a=JSON.parse(value||'[]');return Array.isArray(a)?a.map(v=>[v.name,v.option].filter(Boolean).join(': ')).join(', '):''}catch{return String(value||'')}};
const websiteOptions=()=>'<option value="">Not matched</option>'+options(data.website,w=>w.product_id+':'+w.variation_id,w=>[w.product_name,w.variation_name,w.sku,attributeLabel(w.attributes),fmt(w.active_price_inc_vat)].filter(Boolean).join(' · '));
function bodyFor(r){return r.sheet_body?{...r.sheet_body}:{website_origin:!!r.website_origin,manual_name:r.manual_name||'',manual_code:r.manual_code||'',manual_category:r.manual_category||'',manual_basis:r.manual_basis||'weight',id:r.id||0,version:r.version||0,product_id:r.product_id,size_conversion_id:r.size_conversion_id??'',packaging_setup_id:r.packaging_setup_id||0,packaging_material_id:r.packaging_material_id||0,packaging_mode:r.packaging_mode||'setup',packaging_manual_cost:r.packaging_manual_cost??'',packaging_confirmed:!!r.packaging_confirmed,website_key:r.website_key||'',selling_price_inc_vat:r.selling_price_inc_vat??'',vat_treatment:r.vat_treatment||'',vat_rate:r.vat_rate??data.settings.retail_vat_rate??15,effective_date:r.effective_date||localDate(),source_token:r.source_token,website_confirmed:!!r.saved&&!!r.website_key}}
function draftFor(r){const k=key(r);if(!drafts.has(k)){r.sheet_key=r.sheet_key||(r.id?'price-row-'+r.id:'sheet-'+crypto.randomUUID());drafts.set(k,{original:r,row:{...r},body:bodyFor(r),ack:r.sheet_revision||r.saved?JSON.stringify(bodyFor(r)):null,sheetKey:r.sheet_key,serverRevision:r.sheet_revision||0,revision:0,busy:false,error:''})}return drafts.get(k)}
