function pendingCount(){return [...drafts.values()].filter(d=>d.busy||d.inflight||JSON.stringify(d.body)!==d.ack).length}
function calculateDraft(d){
 const b=d.body,r=d.row,price=b.selling_price_inc_vat===''?null:Number(b.selling_price_inc_vat),vat=['zero','exempt'].includes(b.vat_treatment)?0:num(b.vat_rate);
 r.selling_price_inc_vat=Number.isFinite(price)?price:null;r.selling_price_ex_vat=r.selling_price_inc_vat==null||!['standard','zero','exempt'].includes(b.vat_treatment)?null:r.selling_price_inc_vat/(1+vat/100);
 const known=r.known_cost_ex_vat??r.total_cost_ex_vat;r.profit_per_unit=r.selling_price_ex_vat==null||known==null||(known<=0&&r.total_cost_ex_vat==null)?null:r.selling_price_ex_vat-known;
 r.markup_percent=r.profit_per_unit!=null&&known>0?r.profit_per_unit/known*100:null;
 r.margin_percent=r.profit_per_unit!=null&&r.selling_price_ex_vat>0?r.profit_per_unit/r.selling_price_ex_vat*100:null;
 r.projected_profit=['standard','zero','exempt'].includes(b.vat_treatment)&&r.website_stock_quantity!=null&&r.website_price_inc_vat!=null&&r.total_cost_ex_vat!=null?r.website_stock_quantity*(r.website_price_inc_vat/(1+vat/100)-r.total_cost_ex_vat):null;
 r.website_price_differs=r.website_price_inc_vat!=null&&r.selling_price_inc_vat!=null&&Math.abs(r.website_price_inc_vat-r.selling_price_inc_vat)>.005;
 r.issues=(r.issues||[]).filter(v=>!['Selling Price Required','Low Margin','Loss-Making'].includes(v));if(!(r.selling_price_inc_vat>0))r.issues.push('Selling Price Required');if(r.profit_per_unit<0)r.issues.push('Loss-Making');else if(r.margin_percent!=null&&r.margin_percent<num(data.settings.retail_low_margin_threshold??20))r.issues.push('Low Margin');
 r.completion_status=(r.issues||[]).some(i=>/Review|Estimate/.test(i))?'Needs Review':r.total_cost_ex_vat!=null&&r.selling_price_ex_vat!=null&&r.selling_price_inc_vat>0?'Complete':'Incomplete';r.status=r.product_cost_per_unit==null?(b.size_conversion_id===''?'Not Started':'Costing Required'):r.packaging_cost_ex_vat==null?'Packaging Required':b.packaging_mode==='manual'&&!b.packaging_confirmed?'Packaging Estimate':!(r.selling_price_inc_vat>0)||r.selling_price_ex_vat==null?'Not Started':r.profit_per_unit<0?'Loss-Making':r.margin_percent<num(data.settings.retail_low_margin_threshold??20)?'Low Margin':'Pricing Complete';
}
function filteredRows(){const f=Object.fromEntries(new FormData($('[data-rp-filters]'))),q=(f.q||'').trim().toLowerCase();return allRows().filter(original=>{const r=drafts.get(key(original))?.row||original;return(!q||[r.product_name,r.short_code,r.category,r.supplier,r.website_name,r.website_sku,r.size_label].join(' ').toLowerCase().includes(q))&&(!f.category||f.category===r.category)&&(!f.supplier||f.supplier===r.supplier)&&(!f.basis||f.basis===r.basis)&&(!f.size||f.size===String(r.size_conversion_id))&&(!f.status||(r.completion_status||'Incomplete')===f.status)&&(!f.website||(f.website==='matched'?!!r.website_key:!r.website_key))&&(!f.margin||(r.margin_percent!=null&&(f.margin==='negative'?r.margin_percent<0:f.margin==='low'?r.margin_percent>=0&&r.margin_percent<20:r.margin_percent>=20)))})}
