function refreshPackaging(tr,d){const b=d.body,select=$('[data-packaging]',tr),html=packagingOptions(b);if(select.innerHTML!==html)select.innerHTML=html;select.value=b.packaging_mode==='material'?'material-'+b.packaging_material_id:b.packaging_mode==='setup'&&num(b.packaging_setup_id)?'setup-'+b.packaging_setup_id:b.packaging_mode||'setup';const input=$('[data-pack-manual-inline]',tr);input.hidden=b.packaging_mode!=='manual';if(document.activeElement!==input)input.value=b.packaging_manual_cost??'';$('[data-pack-check]',tr).hidden=b.packaging_mode!=='manual';$('[data-pack-confirm-inline]',tr).checked=!!b.packaging_confirmed;$('[data-pack-summary]',tr).textContent=d.row.packaging_cost_ex_vat==null?'Missing Packaging Cost':fmt(d.row.packaging_cost_ex_vat);}
root.addEventListener('change',async e=>{const tr=e.target.closest('[data-row]');if(!tr||!e.target.matches('[data-packaging],[data-pack-confirm-inline]'))return;const d=draftFor(findRow(tr.dataset.row));clearTimeout(d.timer);if(e.target.matches('[data-packaging]')){const value=e.target.value;d.body.packaging_mode=value.startsWith('setup')?'setup':value.startsWith('material-')?'material':value;d.body.packaging_material_id=value.startsWith('material-')?value.slice(9):0;d.body.packaging_setup_id=value.startsWith('setup-')?value.slice(6):0;d.body.packaging_confirmed=value==='none';}else d.body.packaging_confirmed=e.target.checked;retainPending(d);await preview(d);updateRow(tr,d);});
